sys_script_include.script:
var OperationalRequestHelper = Class.create();
OperationalRequestHelper.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    getEpicsFromCatItem: function() {

        // Get a list of epics applicable to a given CI
        var returnEpics = [];

        // Find the CI applicable to this cat item. It will be used in next query as a filter
        var catItemId = this.getParameter('sysparm_catItemId');
        var grCatItem = new GlideRecord('sc_cat_item');
        if (grCatItem.get(catItemId)) {
            var ciId = grCatItem.getValue('u_ci');
            // Get epics that relate to the CI
            var grEpic = new GlideRecord('rm_epic');
            grEpic.addEncodedQuery("active=true^cmdb_ci=" + ciId);
            grEpic.query();

            while (grEpic.next()) {
                returnEpics.push({
                    summary: grEpic.getValue('short_description'),
                    sys_id: grEpic.getValue('sys_id')
                });
            }
        }

        return JSON.stringify(returnEpics);

    },


    getAdGroupeChoices: function() {

        var returnchoices = [];
        var grChoice = new GlideRecord('x_gamlp_cmdb_ad_active_directory_oject');
        grChoice.addEncodedQuery('nameLIKEGS_AAD_Genesys^EQ');
        grChoice.query();

        while (grChoice.next()) {
            returnchoices.push({
                summary: grChoice.getValue('name'),
                sys_id: grChoice.getValue('sys_id')
            });
        }

        return JSON.stringify(returnchoices);

    },

    type: 'OperationalRequestHelper'
});
